   267	// Returns -1 as index, if no wildcard was found.
   268	func findWildcard(path string) (wildcard string, i int, valid bool) {
   269		// Find start
   270		for start, c := range []byte(path) {
   271			// A wildcard starts with ':' (param) or '*' (catch-all)
   272			if c != ':' && c != '*' {
   273				continue
   274			}
