   276			// Find end and check for invalid characters
   277			valid = true
   278			for end, c := range []byte(path[start+1:]) {
   279				switch c {
   280				case '/':
   281					return path[start : start+1+end], start, valid
   282				case ':', '*':
   283					valid = false
   284				}
   285			}
   286			return path[start:], start, valid
   287		}
   288		return "", -1, false
   289	}
