type refRoute struct {
	route string
	segs  []string
}

func refMatch(routes []refRoute, path string) (string, []Param, int) {
	ps := strings.Split(path[1:], "/")
	var out []string
	var outParams []Param
	for _, r := range routes {
		if len(r.segs) != len(ps) {
			continue
		}
		ok := true
		var params []Param
		for i, s := range r.segs {
			if strings.HasPrefix(s, ":") {
				if ps[i] == "" {
					ok = false
					break
				}
				params = append(params, Param{Key: s[1:], Value: ps[i]})
			} else if s != ps[i] {
				ok = false
				break
			}
		}
		if ok {
			out = append(out, r.route)
			outParams = params
		}
	}
	return strings.Join(out, "|"), outParams, len(out)
}

