func TestZZReduce(t *testing.T) {
	routes := []string{"/:p0/:p1", "/:p0/:p1/:p2", "/:p0/abc/:p2", "/:p0/abc/ab", "/a/:p1/:p2/b", "/c/:p1/c"}
	path := "/a/ab"
	want := "/:p0/:p1"
	got, ps := zzTry(routes, path)
	fmt.Printf("start: got=%q params=%v want=%q\n", got, ps, want)
	changed := true
	for changed {
		changed = false
		for i := range routes {
			cand := append(append([]string{}, routes[:i]...), routes[i+1:]...)
			if len(cand) == 0 {
				continue
			}
			keep := false
			for _, r := range cand {
				if r == want {
					keep = true
				}
			}
			if !keep {
				continue
			}
			g, _ := zzTry(cand, path)
			if g != want { // failure still present (missing or wrong match)
				routes = cand
				changed = true
				break
			}
		}
	}
	got, ps = zzTry(routes, path)
	fmt.Printf("reduced: routes=%v path=%q got=%q params=%v want=%q\n", routes, path, got, ps, want)
	tree := &node{}
	for _, r := range routes {
		tree.addRoute(r, fakeHandler(r))
	}
	var dump func(n *node, ind string)
	dump = func(n *node, ind string) {
		fmt.Printf("%spath=%q idx=%q wild=%v type=%d prio=%d h=%v\n", ind, n.path, n.indices, n.wildChild, n.nType, n.priority, n.handlers != nil)
